insert into public.listings (id, kind, slug, title, tagline, region, location, description, highlights, tags, price, price_unit, details, cover_media_id, palette, status, featured, position) values
  ('2ddec79a-83d6-df3f-1c47-bc2356bacdf7', 'villages', 'sari', 'Sari', 'Gateway to Deoria Tal and the Chaukhamba sunrise', 'Garhwal', 'Ukhimath, Rudraprayag', 'A terraced Garhwali village above the Mandakini valley where mornings begin with woodsmoke and a view of the Chaukhamba range. Walk the village lanes, learn how millet and rajma are grown, and trek to Deoria Tal.', array['Terraced fields and slate-roofed houses', 'Short walk to Deoria Tal', 'Village kitchens and seasonal produce']::text[], array['Culture', 'Lakes', 'Photography']::text[], 0, 'free', '{}'::jsonb, '72226a32-01ab-301e-b46e-7075f267a5f0', 'dawn', 'published', true, 0),
  ('54d73339-83f0-1abb-6e19-0152ddd31fa8', 'villages', 'pangot', 'Pangot', 'Oak forests, birdsong and Kumaoni calm', 'Kumaon', 'Near Nainital', 'A forest hamlet known among birders for its oak and rhododendron woods. Slow walks, home-cooked Kumaoni meals and evenings by the fire.', array['Birdwatching trails', 'Oak and rhododendron forest', 'Quiet, low-traffic lanes']::text[], array['Birding', 'Nature', 'Slow travel']::text[], 0, 'free', '{}'::jsonb, 'b8e9f470-1be4-1bd8-bd25-892bcb9951a4', 'pine', 'published', true, 10),
  ('3160a75e-48a4-9e02-a170-697b362acc26', 'villages', 'gangi', 'Gangi', 'A high Tehri village on the old Kedartal route', 'Garhwal', 'Bhilangana valley, Tehri Garhwal', 'One of the higher inhabited villages of the Bhilangana valley, with stone houses, apple orchards and a living tradition of festivals and folk music.', array['Folk music evenings', 'Orchard walks', 'Trailhead for high-altitude treks']::text[], array['Folk culture', 'Treks']::text[], 0, 'free', '{}'::jsonb, null, 'meadow', 'published', false, 20),
  ('268fddd5-58be-02c1-7ca8-0a60a1083332', 'villages', 'munsiyari', 'Munsiyari', 'Panchachuli peaks and Johar valley heritage', 'Kumaon', 'Pithoragarh', 'A mountain town and base for the Johar valley, with a rich trading heritage and uninterrupted views of the Panchachuli massif.', array['Panchachuli viewpoints', 'Johar heritage and handloom', 'Base for Milam and Khaliya Top treks']::text[], array['Peaks', 'Heritage', 'Handloom']::text[], 0, 'free', '{}'::jsonb, '9dffab36-7693-b680-b237-a5e7f72d5cc2', 'snow', 'published', true, 30),
  ('38d09f34-6578-b9ef-0cd1-1701e9632bb9', 'villages', 'jageshwar', 'Jageshwar', 'Cedar groves and ancient stone temples', 'Kumaon', 'Almora', 'A valley of deodar forest sheltering a cluster of centuries-old stone temples. A place for slow mornings and quiet pilgrimage.', array['Temple complex in a deodar forest', 'Short forest walks', 'Aarti at dusk']::text[], array['Heritage', 'Spiritual']::text[], 0, 'free', '{}'::jsonb, '8968c0d5-c871-37f5-9022-754000715f8e', 'dusk', 'published', false, 40),
  ('5fb88bba-bca1-a21c-2909-972bdfe4b229', 'villages', 'mana', 'Mana', 'The last village before the Tibetan frontier', 'Garhwal', 'Badrinath, Chamoli', 'A high-altitude Bhotiya village near Badrinath with woollen-weaving traditions and stories of the Saraswati river. Visit in the open season, and carry the permits and warm layers local authorities advise.', array['Bhotiya weaving and woollens', 'Saraswati river and Vyas Gufa', 'Dramatic high-altitude setting']::text[], array['Frontier', 'Weaving', 'Pilgrimage']::text[], 0, 'free', '{}'::jsonb, 'db726533-2eef-19ed-1123-ee5493b8889f', 'snow', 'published', false, 50),
  ('9d8fc2df-32af-3884-3cb0-83e8525da2b9', 'homestays', 'kunjapuri-stone-house', 'Stone House at Sari', 'Three rooms, one courtyard, a wood-fired kitchen', 'Garhwal', 'Sari, Rudraprayag', 'A family-run stone and slate house. Wake to the sunrise on the peaks, eat Garhwali thali cooked on a chulha, and join the family in the fields.', array['Wood-fired Garhwali meals', 'Rooftop sunrise deck', 'Hosted village walk']::text[], array['Family-run', 'Meals included']::text[], 2400, 'night', '{"homestay":{"rooms":3,"maxGuests":7,"meals":"Breakfast and dinner"}}'::jsonb, null, 'dawn', 'published', true, 60),
  ('d994fd8f-952a-9cac-4f30-ef555af8f4f3', 'homestays', 'oak-nest-pangot', 'Oak Nest, Pangot', 'A birder''s cottage in the forest edge', 'Kumaon', 'Pangot, Nainital', 'Two cosy cottages ringed by oaks, with a verandah made for binoculars and chai. Your host guides early-morning bird walks.', array['Guided bird walks', 'Kumaoni bhatt ki churkani', 'Fireplace evenings']::text[], array['Birding', 'Cottage']::text[], 3200, 'night', '{"homestay":{"rooms":2,"maxGuests":5,"meals":"All meals"}}'::jsonb, null, 'pine', 'published', true, 70),
  ('d6be28aa-4b60-890c-eccb-46f09f1f5335', 'homestays', 'panchachuli-view-home', 'Panchachuli View Home', 'Johar valley hospitality at 2,200 m', 'Kumaon', 'Munsiyari, Pithoragarh', 'A hillside home with large windows facing the Panchachuli range. Learn about Johar weaving from the family loom.', array['Peak-facing rooms', 'Handloom demo', 'Trek briefings']::text[], array['Peaks', 'Weaving']::text[], 2800, 'night', '{"homestay":{"rooms":4,"maxGuests":8,"meals":"Breakfast and dinner"}}'::jsonb, null, 'snow', 'published', false, 80),
  ('0ad6e7a9-6b43-09ad-d3e7-b57abaf5a083', 'homestays', 'deodar-courtyard-jageshwar', 'Deodar Courtyard', 'Sleep beside the cedar forest', 'Kumaon', 'Jageshwar, Almora', 'A traditional Kumaoni house with carved wooden doors, minutes from the Jageshwar temples.', array['Carved wood architecture', 'Temple morning walk', 'Homegrown vegetables']::text[], array['Heritage', 'Quiet']::text[], 2200, 'night', '{"homestay":{"rooms":3,"maxGuests":6,"meals":"All meals"}}'::jsonb, null, 'dusk', 'published', false, 90),
  ('8d68a873-ae69-0c61-77a2-9b31a054e977', 'homestays', 'apple-orchard-gangi', 'Orchard Home, Gangi', 'Apples, folk songs and big night skies', 'Garhwal', 'Gangi, Tehri', 'Stay with a farming family in the high Bhilangana valley. Evenings often end with folk songs around the hearth.', array['Seasonal orchard visit', 'Folk music evenings', 'Stargazing']::text[], array['Farm stay', 'Folk culture']::text[], 2000, 'night', '{"homestay":{"rooms":3,"maxGuests":6,"meals":"All meals"}}'::jsonb, null, 'meadow', 'published', false, 100),
  ('0d7b70ff-e40c-cff1-67ce-4afee15c862c', 'homestays', 'bhotiya-hearth-mana', 'Bhotiya Hearth', 'Warm woollens and butter tea near Badrinath', 'Garhwal', 'Near Mana, Chamoli', 'A simple, warm home run by a Bhotiya family, open in the summer season. Hear stories of the trade route and try local woollen craft.', array['Seasonal stay', 'Weaving visit', 'Local Bhotiya dishes']::text[], array['Seasonal', 'Cultural']::text[], 2600, 'night', '{"homestay":{"rooms":2,"maxGuests":4,"meals":"Breakfast and dinner"}}'::jsonb, null, 'snow', 'published', false, 110),
  ('15558265-4059-3ed3-e7bc-af183c306e74', 'experiences', 'garhwali-cooking-class', 'Garhwali Kitchen Class', 'Cook phaanu, jhangora kheer and kandali saag', 'Garhwal', 'Sari, Rudraprayag', 'Learn mountain staples from a village host: grind spices on the sil-batta, stir a pot over the chulha and eat what you cook.', array['Hands-on, 3 hours', 'Seasonal ingredients', 'Recipe card to take home']::text[], array['Food', 'Culture']::text[], 1200, 'person', '{}'::jsonb, null, 'dawn', 'published', true, 120),
  ('50ad9097-7cdb-0b48-14b6-5eab052e7107', 'experiences', 'aipan-art-workshop', 'Aipan Art Workshop', 'Kumaoni ritual art with rice-paste and geru', 'Kumaon', 'Almora', 'Paint traditional Aipan patterns with a local artist, and learn the stories behind each motif.', array['Materials included', 'Taught by local artists', 'Take your artwork home']::text[], array['Craft', 'Art']::text[], 900, 'person', '{}'::jsonb, null, 'dusk', 'published', false, 130),
  ('b75208c7-25c8-c1b8-ae44-2363b4ae164a', 'experiences', 'folk-music-evening', 'Folk Music Evening', 'Jagar, Choliya and Jhora under the stars', 'Garhwal', 'Gangi, Tehri', 'An evening of dhol, damau and songs with village musicians. A respectful, community-led programme.', array['Live village musicians', 'Tea and snacks', 'Proceeds go to the performers']::text[], array['Music', 'Community']::text[], 700, 'person', '{}'::jsonb, null, 'meadow', 'published', false, 140),
  ('456c5281-a60c-82c9-807c-1faa8e69e480', 'experiences', 'forest-bird-walk', 'Dawn Bird Walk', 'Himalayan monal, barbets and warblers', 'Kumaon', 'Pangot, Nainital', 'A guided walk with a local naturalist. Binocular loan included. Sightings depend on season and luck.', array['Local naturalist guide', 'Binoculars provided', 'Breakfast after the walk']::text[], array['Birding', 'Nature']::text[], 1000, 'person', '{}'::jsonb, null, 'pine', 'published', true, 150),
  ('93d1d107-8e7c-b68c-5a1f-8ffea81860c0', 'experiences', 'wool-weaving-visit', 'Handloom Weaving Visit', 'Meet the weavers of the Johar valley', 'Kumaon', 'Munsiyari, Pithoragarh', 'Visit a weaving cooperative, try the loom, and buy directly from makers.', array['Meet women weavers', 'Try the loom', 'Fair-price purchases']::text[], array['Craft', 'Community']::text[], 600, 'person', '{}'::jsonb, null, 'snow', 'published', false, 160),
  ('4d6e9f9e-f43d-40e6-59b5-b96e7d4656e3', 'experiences', 'terrace-farm-day', 'Terrace Farm Day', 'Sow, harvest and eat with a mountain family', 'Garhwal', 'Sari, Rudraprayag', 'Spend a day working alongside a farming family, learn about millet and heirloom grains, then share a meal.', array['Seasonal farm tasks', 'Lunch with the family', 'Learn about millets']::text[], array['Farming', 'Food']::text[], 800, 'person', '{}'::jsonb, null, 'meadow', 'published', false, 170),
  ('9fdae34f-f371-3987-f5f5-9400a7ac3313', 'trekking', 'deoria-tal-chandrashila', 'Deoria Tal–Chandrashila', 'A lake, a summit and 360° of peaks', 'Garhwal', 'Sari to Tungnath', 'A beginner-friendly trek that starts at Sari, visits the mirror-like Deoria Tal and links up with Chopta, Tungnath and Chandrashila.', array['Reflections of Chaukhamba in Deoria Tal', 'Rhododendron forests in spring', 'Summit sunrise at Chandrashila']::text[], array['Beginner', 'Lake', 'Summit']::text[], 8500, 'person', '{"trek":{"difficulty":"Easy","days":4,"maxAltitudeM":4000,"bestSeason":"Mar–Jun, Sep–Nov"}}'::jsonb, '8064333d-dc61-2e35-2d5a-f02696d7ba2e', 'dawn', 'published', true, 180),
