  ('71ed196a-5ae3-6551-2691-805c46fcba2d', 'trekking', 'pindari-glacier', 'Pindari Glacier', 'Walk to the foot of a Kumaon glacier', 'Kumaon', 'Bageshwar', 'A long valley walk through villages, oak forest and rhododendron to the snout of the Pindari glacier.', array['Village-to-village trail', 'Glacier viewpoint', 'Phurkia and Dwali campsites']::text[], array['Glacier', 'Valley']::text[], 14500, 'person', '{"trek":{"difficulty":"Moderate","days":7,"maxAltitudeM":3600,"bestSeason":"Apr–Jun, Sep–Oct"}}'::jsonb, null, 'pine', 'published', true, 200),
  ('33b94d68-28db-ab8c-ed6b-48e3ba52ce85', 'trekking', 'valley-of-flowers', 'Valley of Flowers', 'A UNESCO World Heritage alpine meadow', 'Garhwal', 'Ghangaria, Chamoli', 'A seasonal trek to a high valley bursting with wildflowers in the monsoon. Combine with Hemkund Sahib.', array['Monsoon wildflower bloom', 'Pushpawati river valley', 'Optional Hemkund Sahib']::text[], array['Flowers', 'Monsoon', 'World Heritage']::text[], 11000, 'person', '{"trek":{"difficulty":"Moderate","days":6,"maxAltitudeM":4300,"bestSeason":"Jul–Sep"}}'::jsonb, '9f22294e-16ab-d5c1-2479-56309d6da718', 'meadow', 'published', false, 210),
  ('4d1f7e7d-3a5c-74fe-afa4-88235578fa28', 'trekking', 'roopkund', 'Roopkund', 'The mystery lake at high altitude', 'Garhwal', 'Lohajung, Chamoli', 'A demanding high-altitude trek via Bedni Bugyal and Ali Bugyal to a glacial lake with a famous mystery. Prior fitness training strongly recommended.', array['Bedni and Ali Bugyal meadows', 'Trishul views', 'High pass crossing']::text[], array['High altitude', 'Meadows']::text[], 16500, 'person', '{"trek":{"difficulty":"Challenging","days":8,"maxAltitudeM":4800,"bestSeason":"May–Jun, Sep–Oct"}}'::jsonb, null, 'dusk', 'published', false, 220),
  ('45709522-3684-a164-a0f8-0cebe7df7218', 'trekking', 'nag-tibba', 'Nag Tibba', 'A quick weekend escape near Dehradun', 'Garhwal', 'Pantwari, Tehri', 'A short, scenic trek with camping, ideal for first-timers and weekend breaks.', array['Easy introduction to trekking', 'Camp under the stars', 'Views of Bandarpoonch']::text[], array['Weekend', 'Beginner']::text[], 4500, 'person', '{"trek":{"difficulty":"Easy","days":2,"maxAltitudeM":3000,"bestSeason":"Oct–Mar"}}'::jsonb, null, 'pine', 'published', false, 230),
  ('42e1746c-823d-483a-b68a-4e22e1409cbc', 'workation', 'sari-work-nest', 'Sari Work Nest', 'Deskside peaks, power backup and quiet', 'Garhwal', 'Sari, Rudraprayag', 'A homestay with a dedicated work room and ergonomic desk. Weekly rates include meals and a guided village walk.', array['Dedicated desk and chair', 'Backup power', 'Weekly rate discounts']::text[], array['Quiet', 'Meals included']::text[], 3200, 'night', '{"homestay":{"rooms":2,"maxGuests":4,"meals":"All meals"},"workation":{"wifiMbps":40,"powerBackup":true,"deskSetup":true}}'::jsonb, null, 'dawn', 'published', true, 240),
  ('58d8d8ac-83d1-5365-7f09-f6ad96c2f934', 'workation', 'pangot-forest-studio', 'Pangot Forest Studio', 'Write, code or design among the oaks', 'Kumaon', 'Pangot, Nainital', 'A forest-edge cottage with fibre broadband and a glass-fronted work corner.', array['Fibre broadband', 'Glass-fronted workspace', 'Evening bird walks']::text[], array['Fibre', 'Cottage']::text[], 3800, 'night', '{"homestay":{"rooms":1,"maxGuests":2,"meals":"Breakfast and dinner"},"workation":{"wifiMbps":80,"powerBackup":true,"deskSetup":true}}'::jsonb, null, 'pine', 'published', false, 250),
  ('48c834b9-4400-2c98-0ef0-58649f41c9d0', 'workation', 'munsiyari-peak-desk', 'Munsiyari Peak Desk', 'A Panchachuli view from your laptop', 'Kumaon', 'Munsiyari, Pithoragarh', 'A comfortable homestay with a peak-facing desk. Connectivity is solid on 4G with a broadband backup.', array['Peak-facing desk', 'Broadband plus 4G backup', 'Weekend trek add-ons']::text[], array['Views', '4G backup']::text[], 3000, 'night', '{"homestay":{"rooms":2,"maxGuests":3,"meals":"Breakfast and dinner"},"workation":{"wifiMbps":25,"powerBackup":true,"deskSetup":true}}'::jsonb, null, 'snow', 'published', false, 260)
